import math

def is_power_of_five(x):
    if x <= 0:
        return False
    if x == 1:
        return True

    # Check if the base 5 logarithm is an integer
    # We use round and check if the difference is negligible, 
    # but for exact integer checks, we should use prime factorization or division.

    # Integer division check:
    while x > 1:
        if x % 5 != 0:
            return False
        x //= 5
    return True

solutions = []
for n in range(3, 16):
    x = (2**n) - 3
    if is_power_of_five(x):
        solutions.append(n)
        print(f"n={n}: 2^{n} - 3 = {x} (Power of 5)")
    else:
        print(f"n={n}: 2^{n} - 3 = {x} (Not a power of 5)")

print("\nSolutions found in the range 3 <= n <= 15:", solutions)

def check(n):
    if n < 3 or n % 4 != 3:
        return "Does not meet necessary condition"

    val = 2**n - 3
    print(f"n={n}, 2^n - 3 = {val}")

    # Check if val is a power of 5
    if val <= 0:
        return "Value is non-positive"

    k = 0
    temp_val = val
    while temp_val > 1 and temp_val % 5 == 0:
        temp_val //= 5
        k += 1

    if temp_val == 1:
        return f"Is 5^{k}"
    else:
        return f"Not a power of 5 (remainder {temp_val})"

# Check candidates n = 3, 7, 11, 15, 19
candidates = [3, 7, 11, 15, 19]
results = {}
for n in candidates:
    results[n] = check(n)

for n, res in results.items():
    print(f"Result for n={n}: {res}")

